-- ==========================================================================
-- supabase/migrations/20260622000004_vault.sql
-- ==========================================================================

-- =====================================================================
-- Vault (#10): encrypted storage for subscriptions, licenses, product
-- keys, and passwords.
--
-- Security model: secret values are encrypted IN THE BROWSER (AES-GCM
-- with a PBKDF2 key derived from a vault passphrase) before being stored.
-- The database only ever holds ciphertext, so even with DB access the
-- secrets are unreadable without the passphrase. The passphrase is never
-- stored — only a verifier (a known string encrypted with the same key)
-- so we can confirm the passphrase on unlock.
-- =====================================================================

-- 1. Per-user vault unlock metadata (salt + verifier, never the passphrase)
CREATE TABLE IF NOT EXISTS public.vault_meta (
  id UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  salt TEXT NOT NULL,        -- base64 PBKDF2 salt
  verifier TEXT NOT NULL,    -- base64 iv:ciphertext of a known plaintext
  created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- 2. Vault items
CREATE TABLE IF NOT EXISTS public.vault_items (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  category TEXT NOT NULL DEFAULT 'password'
    CHECK (category IN ('subscription', 'license', 'product_key', 'password', 'other')),
  name TEXT NOT NULL,
  username TEXT,             -- not secret (account/email)
  url TEXT,                  -- not secret
  secret_cipher TEXT,        -- base64 iv:ciphertext of the password/key
  notes_cipher TEXT,         -- base64 iv:ciphertext of free-form notes
  file_path TEXT,            -- path in the private `vault` bucket (optional)
  file_name TEXT,
  expires_at DATE,           -- e.g. subscription/license renewal date
  created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_vault_items_user_id ON public.vault_items(user_id);

-- 3. RLS: a user can only ever see/manage their own vault rows.
ALTER TABLE public.vault_meta ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.vault_items ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Users manage own vault_meta" ON public.vault_meta;
CREATE POLICY "Users manage own vault_meta"
  ON public.vault_meta FOR ALL TO authenticated
  USING (auth.uid() = id) WITH CHECK (auth.uid() = id);

DROP POLICY IF EXISTS "Users manage own vault_items" ON public.vault_items;
CREATE POLICY "Users manage own vault_items"
  ON public.vault_items FOR ALL TO authenticated
  USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);

-- 4. Private storage bucket for attached license/subscription files.
INSERT INTO storage.buckets (id, name, public)
VALUES ('vault', 'vault', false)
ON CONFLICT (id) DO NOTHING;

-- Only the owning user can read/write their files (path is prefixed with
-- their user id: `${auth.uid()}/...`).
DROP POLICY IF EXISTS "Users read own vault files" ON storage.objects;
CREATE POLICY "Users read own vault files"
  ON storage.objects FOR SELECT TO authenticated
  USING (bucket_id = 'vault' AND (storage.foldername(name))[1] = auth.uid()::text);

DROP POLICY IF EXISTS "Users write own vault files" ON storage.objects;
CREATE POLICY "Users write own vault files"
  ON storage.objects FOR INSERT TO authenticated
  WITH CHECK (bucket_id = 'vault' AND (storage.foldername(name))[1] = auth.uid()::text);

DROP POLICY IF EXISTS "Users update own vault files" ON storage.objects;
CREATE POLICY "Users update own vault files"
  ON storage.objects FOR UPDATE TO authenticated
  USING (bucket_id = 'vault' AND (storage.foldername(name))[1] = auth.uid()::text);

DROP POLICY IF EXISTS "Users delete own vault files" ON storage.objects;
CREATE POLICY "Users delete own vault files"
  ON storage.objects FOR DELETE TO authenticated
  USING (bucket_id = 'vault' AND (storage.foldername(name))[1] = auth.uid()::text);


-- ==========================================================================
-- supabase/migrations/20260622000005_enable_realtime.sql
-- ==========================================================================

-- =====================================================================
-- Enable Supabase Realtime for live team collaboration.
-- A table only emits postgres_changes events if it belongs to the
-- `supabase_realtime` publication. `jobs` was already enabled (used by the
-- public share page); this adds the remaining shared tables so every
-- teammate's open tabs update within ~1s when anyone makes a change.
--
-- Idempotent: each table is added only if not already a publication member.
-- Realtime still respects RLS, so users only receive rows they can read.
-- =====================================================================
DO $$
DECLARE
  t text;
  tables text[] := ARRAY['jobs', 'clients', 'projects', 'contacts', 'inventory', 'gear_templates'];
BEGIN
  FOREACH t IN ARRAY tables LOOP
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = t)
       AND NOT EXISTS (
         SELECT 1 FROM pg_publication_tables
         WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = t
       )
    THEN
      EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE public.%I', t);
    END IF;
  END LOOP;
END $$;


-- ==========================================================================
-- supabase/migrations/20260623000000_notification_integrations.sql
-- ==========================================================================

-- =====================================================================
-- Team notification integrations
--
-- Generalizes the single hard-coded Discord webhook into a per-org
-- notification engine:
--   * notification_channels  — connected platforms (Discord/Slack/Teams)
--   * notification_events     — per-event toggle + editable message template
--
-- Job status transitions (e.g. Hold -> Booked) and new-job creation fan
-- out to every enabled channel using the matching event's template.
-- Org is treated as a singleton today (first organizations row), matching
-- how branding is loaded elsewhere; schema stays multi-tenant ready.
-- =====================================================================

-- 1. Channels ----------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.notification_channels (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id UUID REFERENCES public.organizations(id) ON DELETE CASCADE,
  platform TEXT NOT NULL CHECK (platform IN ('discord', 'slack', 'teams')),
  label TEXT,
  webhook_url TEXT,
  enabled BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL,
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL,
  UNIQUE (org_id, platform)
);

CREATE INDEX IF NOT EXISTS idx_notification_channels_org_id
  ON public.notification_channels(org_id);

-- 2. Event rules -------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.notification_events (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id UUID REFERENCES public.organizations(id) ON DELETE CASCADE,
  event_key TEXT NOT NULL,
  enabled BOOLEAN NOT NULL DEFAULT false,
  message_template TEXT,
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL,
  UNIQUE (org_id, event_key)
);

CREATE INDEX IF NOT EXISTS idx_notification_events_org_id
  ON public.notification_events(org_id);

-- 3. Seed default channels (disabled, no URL) + event rules ------------
-- One channel placeholder per platform so the settings UI has a row to
-- edit. If a DISCORD_WEBHOOK_URL was used before, paste it into the
-- Discord channel from Settings -> Integrations.
INSERT INTO public.notification_channels (org_id, platform, label, enabled)
SELECT o.id, p.platform, p.label, false
FROM (SELECT id FROM public.organizations ORDER BY created_at LIMIT 1) o
CROSS JOIN (VALUES
  ('discord', 'Discord'),
  ('slack',   'Slack'),
  ('teams',   'Microsoft Teams')
) AS p(platform, label)
ON CONFLICT (org_id, platform) DO NOTHING;

-- Event rules. Only job_created + status_booked ship enabled; the rest
-- are available but off until a team toggles them on in the app.
INSERT INTO public.notification_events (org_id, event_key, enabled, message_template)
SELECT o.id, e.event_key, e.enabled, e.message_template
FROM (SELECT id FROM public.organizations ORDER BY created_at LIMIT 1) o
CROSS JOIN (VALUES
  ('job_created',      true,  '🎬 **New Production Added!** {title} for {client} — shoot {shoot_date} @ {location}'),
  ('status_planning',  false, '📝 **{title}** moved to Planning (was {old_status}).'),
  ('status_hold',      false, '⏳ **{title}** is now on Hold (was {old_status}).'),
  ('status_booked',    true,  '✅ **BOOKED!** {title} for {client} is confirmed for {shoot_date} @ {location}. (was {old_status})'),
  ('status_wrapped',   false, '🎉 **{title}** is Wrapped! Great work team.'),
  ('status_cancelled', false, '❌ **{title}** for {client} was Cancelled (was {old_status}).')
) AS e(event_key, enabled, message_template)
ON CONFLICT (org_id, event_key) DO NOTHING;

-- 4. RLS ---------------------------------------------------------------
-- Mirror the organizations pattern: any authenticated user can read,
-- only admins can write. Webhook URLs are sensitive, so no public read.
ALTER TABLE public.notification_channels ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.notification_events ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Authenticated can read notification_channels" ON public.notification_channels;
CREATE POLICY "Authenticated can read notification_channels"
  ON public.notification_channels FOR SELECT TO authenticated USING (true);

DROP POLICY IF EXISTS "Admins manage notification_channels" ON public.notification_channels;
CREATE POLICY "Admins manage notification_channels"
  ON public.notification_channels FOR ALL TO authenticated
  USING (
    EXISTS (SELECT 1 FROM public.user_roles WHERE user_roles.id = auth.uid() AND user_roles.role = 'admin')
  );

DROP POLICY IF EXISTS "Authenticated can read notification_events" ON public.notification_events;
CREATE POLICY "Authenticated can read notification_events"
  ON public.notification_events FOR SELECT TO authenticated USING (true);

DROP POLICY IF EXISTS "Admins manage notification_events" ON public.notification_events;
CREATE POLICY "Admins manage notification_events"
  ON public.notification_events FOR ALL TO authenticated
  USING (
    EXISTS (SELECT 1 FROM public.user_roles WHERE user_roles.id = auth.uid() AND user_roles.role = 'admin')
  );


-- ==========================================================================
-- supabase/migrations/20260623120000_shotlist_grid.sql
-- ==========================================================================

-- Workstream A: Spreadsheet-style shotlist (Production Bible parity)
-- Adds scene-level metadata and the extra per-shot columns the producer's
-- Google Sheets shotlist uses (timing, subject, movement, lens, animation
-- link, timecode, lyrics, notes, take/best, est takes, priority).

-- Scene / "Setup" metadata: one row per scene within a job.
CREATE TABLE IF NOT EXISTS job_scenes (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  job_id UUID REFERENCES jobs(id) ON DELETE CASCADE,
  setup_number TEXT,
  name TEXT,
  timecode TEXT,
  description TEXT,
  notes TEXT,
  est_minutes TEXT,
  sort_order INTEGER DEFAULT 0,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

ALTER TABLE job_scenes ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Allow all for now" ON job_scenes;
CREATE POLICY "Allow all for now" ON job_scenes FOR ALL USING (true) WITH CHECK (true);
CREATE INDEX IF NOT EXISTS idx_job_scenes_job_id ON job_scenes (job_id);

-- Extend the shotlist with the spreadsheet columns. scene_id links a shot to
-- its job_scenes row; scene_group (existing TEXT) is kept as a label fallback.
ALTER TABLE public.job_shotlist
  ADD COLUMN IF NOT EXISTS scene_id UUID REFERENCES job_scenes(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS timing TEXT,
  ADD COLUMN IF NOT EXISTS subject TEXT,
  ADD COLUMN IF NOT EXISTS movement TEXT,
  ADD COLUMN IF NOT EXISTS lens TEXT,
  ADD COLUMN IF NOT EXISTS animation_link TEXT,
  ADD COLUMN IF NOT EXISTS animation_label TEXT,
  ADD COLUMN IF NOT EXISTS timecode TEXT,
  ADD COLUMN IF NOT EXISTS lyrics TEXT,
  ADD COLUMN IF NOT EXISTS notes TEXT,
  ADD COLUMN IF NOT EXISTS take_best TEXT,
  ADD COLUMN IF NOT EXISTS est_takes TEXT,
  ADD COLUMN IF NOT EXISTS priority TEXT DEFAULT 'must';

CREATE INDEX IF NOT EXISTS idx_job_shotlist_scene_id ON public.job_shotlist (scene_id);


-- ==========================================================================
-- supabase/migrations/20260623120001_social_media.sql
-- ==========================================================================

-- Workstream B: Social Media management (manual planner — no platform OAuth).
-- Five tables backing the Content Calendar, Rollout Tracker, Deliverables
-- Tracker, and Link Hub + Caption Library. RLS mirrors the rest of the app
-- ("Allow all for now").

-- 1) Content calendar posts
CREATE TABLE IF NOT EXISTS social_posts (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  client_id UUID REFERENCES clients(id) ON DELETE SET NULL,
  job_id UUID REFERENCES jobs(id) ON DELETE SET NULL,
  title TEXT,
  caption TEXT,
  platform TEXT DEFAULT 'instagram',
  status TEXT DEFAULT 'idea',          -- idea | draft | scheduled | posted
  scheduled_at TIMESTAMPTZ,
  asset_url TEXT,
  link_url TEXT,
  sort_order INTEGER DEFAULT 0,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 2) Rollout campaigns (per release / artist)
CREATE TABLE IF NOT EXISTS social_campaigns (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  client_id UUID REFERENCES clients(id) ON DELETE SET NULL,
  name TEXT NOT NULL,
  release_date DATE,
  status TEXT DEFAULT 'planning',
  notes TEXT,
  sort_order INTEGER DEFAULT 0,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 3) Campaign tasks (phased checklist)
CREATE TABLE IF NOT EXISTS social_campaign_tasks (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  campaign_id UUID REFERENCES social_campaigns(id) ON DELETE CASCADE,
  phase TEXT DEFAULT 'teaser',         -- teaser | release | post
  task TEXT NOT NULL,
  owner TEXT,
  due_date DATE,
  is_done BOOLEAN DEFAULT false,
  sort_order INTEGER DEFAULT 0,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 4) Deliverables (cutdowns per platform/format)
CREATE TABLE IF NOT EXISTS social_deliverables (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  client_id UUID REFERENCES clients(id) ON DELETE SET NULL,
  job_id UUID REFERENCES jobs(id) ON DELETE SET NULL,
  label TEXT,
  format TEXT DEFAULT '9:16',
  duration TEXT,
  platform TEXT DEFAULT 'instagram',
  status TEXT DEFAULT 'todo',          -- todo | in_progress | delivered
  asset_url TEXT,
  sort_order INTEGER DEFAULT 0,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 5) Link hub + caption library
CREATE TABLE IF NOT EXISTS social_links (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  client_id UUID REFERENCES clients(id) ON DELETE SET NULL,
  kind TEXT DEFAULT 'link',            -- link | caption
  label TEXT,
  url TEXT,
  body TEXT,
  platform TEXT,
  tags TEXT,
  sort_order INTEGER DEFAULT 0,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- RLS
DO $$
DECLARE t TEXT;
BEGIN
  FOREACH t IN ARRAY ARRAY['social_posts','social_campaigns','social_campaign_tasks','social_deliverables','social_links']
  LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY;', t);
    EXECUTE format('DROP POLICY IF EXISTS "Allow all for now" ON %I;', t);
    EXECUTE format('CREATE POLICY "Allow all for now" ON %I FOR ALL USING (true) WITH CHECK (true);', t);
  END LOOP;
END $$;

CREATE INDEX IF NOT EXISTS idx_social_posts_client ON social_posts (client_id);
CREATE INDEX IF NOT EXISTS idx_social_campaign_tasks_campaign ON social_campaign_tasks (campaign_id);
CREATE INDEX IF NOT EXISTS idx_social_deliverables_client ON social_deliverables (client_id);
CREATE INDEX IF NOT EXISTS idx_social_links_client ON social_links (client_id);


