-- ==========================================================================
-- supabase/migrations/20260706000002_security_hardening.sql
-- ==========================================================================

-- Security hardening ahead of multi-user beta.
--
-- Until now most tables carried permissive "allow all" RLS policies. The anon
-- key ships in the browser bundle, so that made the database publicly
-- readable/writable to anyone who inspected the site. This migration:
--   1. Locks google_tokens to the service role only (OAuth tokens must never
--      be client-readable — the UI now checks /api/auth/google/status).
--   2. Requires an authenticated session on all internal tables.
--   3. Keeps anonymous READ on jobs + inventory (the public gear-share page
--      depends on it); writes there require authentication (share-page edits
--      go through /api/share/gear with the service key).
--
-- Because permissive policies are OR'd together, every pre-existing policy on
-- the affected tables is dropped first.

DO $$
DECLARE
  t TEXT;
  pol RECORD;
  internal_tables TEXT[] := ARRAY[
    'contacts', 'clients', 'projects', 'job_roles', 'job_schedules',
    'job_scenes', 'job_shotlist', 'job_todos', 'job_templates',
    'gear_templates', 'organizations', 'profiles', 'notification_channels',
    'notification_events', 'vault_meta', 'vault_items', 'budget_items',
    'calendar_events', 'social_campaigns', 'social_campaign_tasks',
    'social_deliverables', 'social_links', 'social_posts'
  ];
  public_read_tables TEXT[] := ARRAY['jobs', 'inventory'];
BEGIN
  -- 1. google_tokens: drop every policy, leave RLS on with no policies at all
  --    → only the service role (which bypasses RLS) can touch it.
  IF EXISTS (SELECT 1 FROM pg_tables WHERE schemaname = 'public' AND tablename = 'google_tokens') THEN
    FOR pol IN SELECT policyname FROM pg_policies WHERE schemaname = 'public' AND tablename = 'google_tokens'
    LOOP
      EXECUTE format('DROP POLICY %I ON google_tokens', pol.policyname);
    END LOOP;
    EXECUTE 'ALTER TABLE google_tokens ENABLE ROW LEVEL SECURITY';
  END IF;

  -- 2. Internal tables: authenticated users only.
  FOREACH t IN ARRAY internal_tables
  LOOP
    IF EXISTS (SELECT 1 FROM pg_tables WHERE schemaname = 'public' AND tablename = t) THEN
      FOR pol IN SELECT policyname FROM pg_policies WHERE schemaname = 'public' AND tablename = t
      LOOP
        EXECUTE format('DROP POLICY %I ON %I', pol.policyname, t);
      END LOOP;
      EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
      EXECUTE format(
        'CREATE POLICY "Authenticated full access" ON %I FOR ALL TO authenticated USING (true) WITH CHECK (true)', t);
    END IF;
  END LOOP;

  -- 3. jobs + inventory: anonymous read (public gear share), authed writes.
  FOREACH t IN ARRAY public_read_tables
  LOOP
    IF EXISTS (SELECT 1 FROM pg_tables WHERE schemaname = 'public' AND tablename = t) THEN
      FOR pol IN SELECT policyname FROM pg_policies WHERE schemaname = 'public' AND tablename = t
      LOOP
        EXECUTE format('DROP POLICY %I ON %I', pol.policyname, t);
      END LOOP;
      EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
      EXECUTE format('CREATE POLICY "Public read" ON %I FOR SELECT USING (true)', t);
      EXECUTE format('CREATE POLICY "Authenticated insert" ON %I FOR INSERT TO authenticated WITH CHECK (true)', t);
      EXECUTE format('CREATE POLICY "Authenticated update" ON %I FOR UPDATE TO authenticated USING (true) WITH CHECK (true)', t);
      EXECUTE format('CREATE POLICY "Authenticated delete" ON %I FOR DELETE TO authenticated USING (true)', t);
    END IF;
  END LOOP;

  -- user_roles is intentionally untouched: its policies were purpose-built by
  -- earlier migrations (self-healing login lookup) and remain as-is.
END $$;


-- ==========================================================================
-- supabase/migrations/20260706000003_production_notes.sql
-- ==========================================================================

-- Production Notes: the team's meeting-notes / docs library. Every note can
-- be tied to a client and/or production so notes sort themselves instead of
-- living in one long Google Doc.
CREATE TABLE IF NOT EXISTS production_notes (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  title TEXT NOT NULL DEFAULT 'Untitled Note',
  body TEXT NOT NULL DEFAULT '',
  job_id UUID REFERENCES jobs(id) ON DELETE SET NULL,
  client_id UUID REFERENCES clients(id) ON DELETE SET NULL,
  tags TEXT,
  pinned BOOLEAN NOT NULL DEFAULT FALSE,
  created_by TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

ALTER TABLE production_notes ENABLE ROW LEVEL SECURITY;

-- Authenticated team members only (matches the security-hardening migration).
DROP POLICY IF EXISTS "Authenticated full access" ON production_notes;
CREATE POLICY "Authenticated full access" ON production_notes
  FOR ALL TO authenticated USING (true) WITH CHECK (true);

CREATE INDEX IF NOT EXISTS idx_production_notes_job_id ON production_notes (job_id);
CREATE INDEX IF NOT EXISTS idx_production_notes_client_id ON production_notes (client_id);
CREATE INDEX IF NOT EXISTS idx_production_notes_updated_at ON production_notes (updated_at DESC);

-- Realtime, only if not already a member (so this file can run twice).
DO $$
DECLARE t TEXT;
BEGIN
  FOREACH t IN ARRAY ARRAY['production_notes'] LOOP
    IF NOT EXISTS (
      SELECT 1 FROM pg_publication_tables
      WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = t
    ) THEN
      EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE public.%I', t);
    END IF;
  END LOOP;
END $$;


-- ==========================================================================
-- supabase/migrations/20260717000000_crew_order_tracker_optin_google_events.sql
-- ==========================================================================

-- 1. Crew manifest ordering: lets producers control the order crew appear in
--    on the Call Sheet / Master Brief exports. NULLs sort last, so existing
--    rows keep their current (insertion) order until explicitly reordered.
ALTER TABLE job_roles ADD COLUMN IF NOT EXISTS sort_order INTEGER;

-- 2. Edit Tracker is opt-in: new jobs no longer land on the post board
--    automatically. The board already filters on edit_status being set; the
--    old DEFAULT 'Filmed' defeated that by stamping every new job.
ALTER TABLE jobs ALTER COLUMN edit_status DROP DEFAULT;

-- 3. Google Calendar import: calendar sync can now pull the team's regular
--    Google events in as calendar markers. The google_event_id makes the
--    import idempotent (re-syncs update instead of duplicating). Unique index
--    on a nullable column still allows unlimited manual markers (NULLs are
--    distinct in Postgres).
ALTER TABLE calendar_events ADD COLUMN IF NOT EXISTS google_event_id TEXT;
CREATE UNIQUE INDEX IF NOT EXISTS idx_calendar_events_google_event_id
  ON calendar_events (google_event_id);


-- ==========================================================================
-- supabase/migrations/20260717000001_google_sync_status.sql
-- ==========================================================================

-- Sync health tracking: every calendar pull (cron, silent, or manual) records
-- its outcome here so the UI can show "last synced X ago / sync failing"
-- instead of letting a dead Google token fail silently in the background.
ALTER TABLE public.google_tokens
  ADD COLUMN IF NOT EXISTS last_sync_at TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS last_sync_ok BOOLEAN,
  ADD COLUMN IF NOT EXISTS last_sync_error TEXT;


-- ==========================================================================
-- supabase/migrations/20260717000002_team_synced_prefs.sql
-- ==========================================================================

-- Preferences that used to live only in one browser's localStorage now sync:
--   organizations.custom_tabs       — the team's Command Center tab layout
--   organizations.saved_gear_owners — gear builder's remembered owner names
--   profiles.scratch_notes          — each user's dashboard scratchpad
-- localStorage remains the instant fallback layer; these are authoritative
-- when present (see src/lib/team-prefs.ts).
ALTER TABLE public.organizations
  ADD COLUMN IF NOT EXISTS custom_tabs JSONB,
  ADD COLUMN IF NOT EXISTS saved_gear_owners JSONB;

ALTER TABLE public.profiles
  ADD COLUMN IF NOT EXISTS scratch_notes TEXT;


-- ==========================================================================
-- supabase/migrations/20260717000003_calendar_marker_tombstones.sql
-- ==========================================================================

-- Deletion round-trip for imported Google Calendar markers:
--   * hidden=true is a tombstone: a teammate removed the marker in-app, and
--     re-syncs must not resurrect it (upserts never touch `hidden`).
--   * Events cancelled/deleted on the Google side are removed here by the
--     sync (it now requests showDeleted and deletes matching rows outright).
ALTER TABLE public.calendar_events
  ADD COLUMN IF NOT EXISTS hidden BOOLEAN DEFAULT false;


-- ==========================================================================
-- supabase/migrations/20260805000000_quickbooks.sql
-- ==========================================================================

-- QuickBooks Online connection (read-only usage).
--
-- Mirrors google_tokens: one row per connected user, service-role access only,
-- never selectable from the browser. realm_id is the QuickBooks company id and
-- is required on every API call, so it is stored alongside the tokens.
--
-- Intuit refresh tokens rotate on every use — the new one must be persisted or
-- the connection dies — and expire after 100 days of inactivity, so
-- refresh_token_expires_at is tracked to let the UI warn before that happens.
CREATE TABLE IF NOT EXISTS public.quickbooks_tokens (
  id UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  realm_id TEXT NOT NULL,
  access_token TEXT NOT NULL,
  refresh_token TEXT NOT NULL,
  expires_at TIMESTAMPTZ NOT NULL,
  refresh_token_expires_at TIMESTAMPTZ,
  -- Sync health, same shape as google_tokens, for the Integrations chip.
  last_sync_at TIMESTAMPTZ,
  last_sync_ok BOOLEAN,
  last_sync_error TEXT,
  updated_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now()) NOT NULL
);

ALTER TABLE public.quickbooks_tokens ENABLE ROW LEVEL SECURITY;

-- No policy is granted deliberately: every read goes through the service role
-- in an API route. Tokens must never be readable from the client.

-- Link a Studio OS client to its QuickBooks customer. Nullable: matching is
-- best-effort by name and can be corrected by hand later.
ALTER TABLE public.clients
  ADD COLUMN IF NOT EXISTS quickbooks_customer_id TEXT;

CREATE INDEX IF NOT EXISTS idx_clients_quickbooks_customer_id
  ON public.clients (quickbooks_customer_id);


-- ==========================================================================
-- supabase/migrations/20260806000000_user_roles_authenticated_read.sql
-- ==========================================================================

-- Close the anonymous read on user_roles.
--
-- 20260619000007 opened SELECT to everyone ("USING (true)" with no role
-- restriction) to work around a client-side race: the role lookup fired before
-- the Supabase session was attached, so an authenticated-only policy returned
-- nothing and the app fell back to no role. The anon key ships in the browser
-- bundle, so the side effect was that anyone could enumerate every teammate's
-- email address and role.
--
-- The lookup now always runs after a session exists (it needs session.user.id
-- to query by), so restricting to `authenticated` fixes the leak without
-- reintroducing the race. Reads stay unrestricted *within* the signed-in team:
-- the login path's self-healing fallback looks a row up by email before it
-- knows the id, so a strict "only your own row" policy would break it.

DROP POLICY IF EXISTS "Allow read access to everyone" ON public.user_roles;
DROP POLICY IF EXISTS "Allow read access to authenticated users" ON public.user_roles;
-- Drop our own policy too, so running this file a second time is a no-op
-- rather than a "policy already exists" error.
DROP POLICY IF EXISTS "Authenticated read" ON public.user_roles;

CREATE POLICY "Authenticated read"
  ON public.user_roles FOR SELECT
  TO authenticated
  USING (true);


-- ==========================================================================
-- supabase/migrations/20260806000001_share_token.sql
-- ==========================================================================

-- Close the anonymous read on jobs and inventory.
--
-- 20260706000002 granted "Public read USING (true)" on both tables because the
-- gear-share page reads them straight from the browser with the anon key, and
-- the people it is shared with are not signed in. But a table-wide policy can't
-- scope to one job, so the effect was that anyone holding the anon key — which
-- ships in the page bundle — could read every job: client names, contact
-- emails, locations, notes, creative briefs, and the Drive/Discord/review URLs,
-- which are themselves capability links.
--
-- Each job now carries a share_token. The share page reads through
-- /api/share/gear, which checks the token server-side with the service key, so
-- a share link grants exactly one job and nothing else. The public policies go
-- away entirely.
--
-- Existing /share/gear/<id> links stop working: they carry no token, and there
-- is no way to honour them without keeping the hole open. Re-copy the link from
-- Gear → Share to hand out the new one.

-- 1. Per-job share token. Random per row, so knowing one tells you nothing
--    about another, and NOT NULL so a job can never exist unshareable.
ALTER TABLE public.jobs
  ADD COLUMN IF NOT EXISTS share_token UUID NOT NULL DEFAULT gen_random_uuid();

-- Lookups come in as (id, token); the id is already the primary key, so this
-- only needs to make the token side cheap to verify.
CREATE INDEX IF NOT EXISTS jobs_share_token_idx ON public.jobs (share_token);

-- 2. Drop anonymous read on both tables and require a session. The writes were
--    already authenticated-only; they are recreated here so the full policy set
--    for these tables lives in one place.
DO $$
DECLARE
  t TEXT;
  pol RECORD;
  tables TEXT[] := ARRAY['jobs', 'inventory'];
BEGIN
  FOREACH t IN ARRAY tables
  LOOP
    IF EXISTS (SELECT 1 FROM pg_tables WHERE schemaname = 'public' AND tablename = t) THEN
      -- Permissive policies are OR'd together, so the old "Public read" has to
      -- go rather than simply be joined by a stricter one.
      FOR pol IN SELECT policyname FROM pg_policies WHERE schemaname = 'public' AND tablename = t
      LOOP
        EXECUTE format('DROP POLICY %I ON %I', pol.policyname, t);
      END LOOP;

      EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
      EXECUTE format(
        'CREATE POLICY "Authenticated full access" ON %I FOR ALL TO authenticated USING (true) WITH CHECK (true)', t);
    END IF;
  END LOOP;
END $$;


-- ==========================================================================
-- supabase/migrations/20260806000002_restore_inventory_public_read.sql
-- ==========================================================================

-- Restore anonymous read on inventory.
--
-- 20260806000001 locked down jobs and inventory together, on the reasoning that
-- both were only public to serve the gear-share page. That was right about jobs
-- and wrong about inventory: /gear/inventory is a public marketing page on
-- zipline.media. It has no auth, reads the catalog straight from the browser,
-- and renders a total replacement value as a selling point. Locking the table
-- left that page empty for every signed-out visitor.
--
-- The two tables deserve different answers. jobs holds client names, contact
-- emails, notes, and capability URLs, and stays authenticated-only behind the
-- per-job share token. inventory holds item name, category, quantity, and
-- replacement cost — the catalog the public page exists to show.
--
-- Writes stay authenticated. Only SELECT opens back up.

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_tables WHERE schemaname = 'public' AND tablename = 'inventory') THEN
    DROP POLICY IF EXISTS "Public read" ON public.inventory;
    CREATE POLICY "Public read"
      ON public.inventory FOR SELECT
      USING (true);
  END IF;
END $$;


-- ==========================================================================
-- supabase/migrations/20260806000003_deliverables_by_job.sql
-- ==========================================================================

-- Deliverables pinned to a production.
--
-- social_deliverables has carried a job_id column since it was created, but
-- nothing ever set it — the Social tab only ever links a deliverable to a
-- client. Slate cards now read and write that column, so a shoot carries the
-- list of cutdowns it owes.
--
-- Deliberately the same table rather than a new job_deliverables one: a
-- deliverable is the same object whichever screen you reached it from, and two
-- competing lists would drift the first time someone edited the "wrong" one.
--
-- Only the index is new. The Slate board queries by job_id for every card on
-- screen at once, which without this is a sequential scan per board load.

CREATE INDEX IF NOT EXISTS idx_social_deliverables_job
  ON public.social_deliverables (job_id);


-- ==========================================================================
-- supabase/migrations/20260806000004_self_provision_client_role.sql
-- ==========================================================================

-- Let a new sign-in create its own role row.
--
-- The login path (command-center/page.tsx) looks a user up in user_roles and,
-- finding nothing, inserts { id, email, role: 'client' }. But the only INSERT
-- policy on the table — from 20260620000000 — requires the caller to already
-- be an admin in user_roles:
--
--   WITH CHECK (EXISTS (SELECT 1 FROM user_roles
--                       WHERE id = auth.uid() AND role = 'admin'))
--
-- A brand-new user is by definition not in that table, so the insert is always
-- denied. The error is caught and they fall through to client access for the
-- session, which is why nobody is locked out and nobody is over-privileged —
-- but no row is ever written. They never appear in the Team tab, and the
-- lookup re-runs from scratch on every login.
--
-- This grants exactly the insert the login path attempts and nothing more:
-- your own id, and only the 'client' role. Self-promotion is impossible —
-- role = 'client' is checked, so an attempt to insert 'admin' is refused, and
-- id = auth.uid() stops anyone writing a row for someone else. Admins keep
-- their broader policy for creating teammates at other roles.
--
-- Accounts made through Settings → Team are unaffected either way: that route
-- writes with the service key, which bypasses RLS entirely.

DROP POLICY IF EXISTS "Users can self-provision a client role" ON public.user_roles;

CREATE POLICY "Users can self-provision a client role"
  ON public.user_roles FOR INSERT
  TO authenticated
  WITH CHECK (id = auth.uid() AND role = 'client');


-- ==========================================================================
-- supabase/migrations/20260807000000_job_wrap_time.sql
-- ==========================================================================

-- Wrap time on a production.
--
-- Jobs carried a call time and nothing else, so every calendar event assumed a
-- flat eight-hour day: an 8:00 AM call always ended at 4:00 PM on Google,
-- whatever the shoot actually was. A half-day read as a full one and a
-- fourteen-hour day read as short, which is misleading to anyone reading the
-- calendar to see whether someone is free.
--
-- Text rather than TIME, matching call_time. These are wall-clock strings in
-- the studio's timezone ("6:00 PM"), deliberately not absolute instants — see
-- the note in src/lib/date.ts about why storing them as timestamps is what
-- turned an 8:00 AM call into 4:00 AM on Google Calendar.
--
-- Nullable: most shoots are booked before anyone knows when they'll wrap, and
-- an empty wrap keeps the previous eight-hour estimate rather than forcing a
-- guess at creation time.

ALTER TABLE public.jobs
  ADD COLUMN IF NOT EXISTS wrap_time TEXT;


-- ==========================================================================
-- supabase/migrations/20260807000001_usage_events.sql
-- ==========================================================================

-- Usage tracking, for working out which parts of the app people actually use.
--
-- Deliberately narrow. Each row records that a surface was opened or an action
-- was taken — never what was typed, selected, or saved. There is no field for
-- payloads, so no future call site can quietly start logging a client name or
-- a note into it.
--
-- Vercel Analytics already ships in the layout, but it counts page views and
-- Studio OS is a single route: every tab, every board and every modal is
-- /command-center. It cannot answer "does anyone open the Vault", which is the
-- question this exists for.

CREATE TABLE IF NOT EXISTS public.usage_events (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  -- Who. CASCADE so removing a teammate removes their trail with them rather
  -- than leaving orphaned rows attributable by elimination.
  user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE,
  -- What kind of thing happened: 'view' (a surface was opened) or 'action'.
  kind TEXT NOT NULL,
  -- Where: a tab id like 'calendar', or a component name.
  surface TEXT NOT NULL,
  -- Which action, when kind = 'action'. A fixed label, never user content.
  label TEXT,
  -- 'mobile' or 'desktop', so layout problems can be told apart by device.
  viewport TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- The admin view slices by surface and by day, and prunes by age.
CREATE INDEX IF NOT EXISTS idx_usage_events_created ON public.usage_events (created_at DESC);
CREATE INDEX IF NOT EXISTS idx_usage_events_surface ON public.usage_events (surface);

ALTER TABLE public.usage_events ENABLE ROW LEVEL SECURITY;

-- Anyone signed in may record their own activity, and only their own: user_id
-- is pinned to auth.uid() so one account cannot write events attributed to
-- another.
DROP POLICY IF EXISTS "Record your own usage" ON public.usage_events;
CREATE POLICY "Record your own usage"
  ON public.usage_events FOR INSERT
  TO authenticated
  WITH CHECK (user_id = auth.uid());

-- Reading is admin-only. Staff should not be able to see what their colleagues
-- clicked, which is a different thing entirely from the owner reviewing usage.
DROP POLICY IF EXISTS "Admins read usage" ON public.usage_events;
CREATE POLICY "Admins read usage"
  ON public.usage_events FOR SELECT
  TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM public.user_roles
      WHERE user_roles.id = auth.uid() AND user_roles.role = 'admin'
    )
  );

-- Admins may clear the log — both to reset between test rounds and so there is
-- a way to delete the record of someone's activity on request.
DROP POLICY IF EXISTS "Admins clear usage" ON public.usage_events;
CREATE POLICY "Admins clear usage"
  ON public.usage_events FOR DELETE
  TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM public.user_roles
      WHERE user_roles.id = auth.uid() AND user_roles.role = 'admin'
    )
  );


-- ==========================================================================
-- supabase/migrations/20260813000000_add_editor_role.sql
-- ==========================================================================

-- Add the 'editor' role: a freelance editor account scoped to the Edit Tracker.
--
-- user_roles.role has carried a CHECK constraint of ('admin','staff','client')
-- since 20260619000001, so Settings → Team could not write the new role at all
-- without this — the insert would fail with a constraint violation.
--
-- Nothing else changes at the database level. Since 20260706000002 the tracker's
-- tables (jobs, job_todos, organizations) are governed by "authenticated" RLS
-- policies rather than per-role ones, so an editor already has exactly the
-- database access they need to move cards; what an account may *reach* is
-- enforced in the app (src/lib/roles.ts), same as for staff and client.
--
-- Constraint names are generated by Postgres for inline CHECKs, so the old one
-- is looked up by the column it guards rather than assumed to be
-- user_roles_role_check.

DO $$
DECLARE
  con RECORD;
BEGIN
  FOR con IN
    SELECT c.conname
    FROM pg_constraint c
    JOIN pg_class t ON t.oid = c.conrelid
    JOIN pg_namespace n ON n.oid = t.relnamespace
    WHERE n.nspname = 'public'
      AND t.relname = 'user_roles'
      AND c.contype = 'c'
      AND pg_get_constraintdef(c.oid) ILIKE '%role%'
  LOOP
    EXECUTE format('ALTER TABLE public.user_roles DROP CONSTRAINT %I', con.conname);
  END LOOP;

  ALTER TABLE public.user_roles
    ADD CONSTRAINT user_roles_role_check
    CHECK (role IN ('admin', 'staff', 'client', 'editor'));
END $$;


-- ==========================================================================
-- supabase/migrations/20260814000000_calendar_event_times.sql
-- ==========================================================================

-- Times on calendar markers.
--
-- calendar_events carried dates and nothing else, so every marker was an
-- all-day block: a 2:00 PM client meeting booked on the Calendar tab covered
-- the whole day here and pushed to Google as an all-day event, which is what
-- made the calendar useless for telling whether an afternoon was actually
-- free. Events imported *from* Google lost their times the same way.
--
-- Text rather than TIME, matching jobs.call_time and jobs.wrap_time. These are
-- wall-clock strings in the studio's timezone ("2:00 PM"), deliberately not
-- absolute instants — see the note in src/lib/date.ts about why storing them
-- as timestamps is what turned an 8:00 AM call into 4:00 AM on Google.
--
-- Both nullable: a marker with no start time stays an all-day entry, which is
-- the right shape for a hold or a day off.

ALTER TABLE public.calendar_events
  ADD COLUMN IF NOT EXISTS start_time TEXT,
  ADD COLUMN IF NOT EXISTS end_time TEXT;


-- ==========================================================================
-- supabase/migrations/20260814000001_contact_secondary_roles.sql
-- ==========================================================================

-- Secondary roles on a contact.
--
-- A contact had exactly one role, primary_role, and every "who can do X?"
-- lookup read it. On a small crew that is wrong more often than it is right —
-- the same person cuts, shoots, and produces depending on the job. Concretely:
-- assigning an edit in the tracker required setting someone's primary role to
-- "Editor", which then listed them as the editor on every call sheet they
-- appeared on.
--
-- primary_role stays the headline — the default title on a call sheet, the one
-- the Rolodex sorts by. secondary_roles are the other hats, and count for
-- role lookups and call-sheet position suggestions.

ALTER TABLE public.contacts
  ADD COLUMN IF NOT EXISTS secondary_roles TEXT[] DEFAULT '{}'::text[];

-- "Everyone who can colour" is a filter on this column across the whole
-- roster, so it is worth an index once a rolodex is more than a few hundred.
CREATE INDEX IF NOT EXISTS idx_contacts_secondary_roles
  ON public.contacts USING GIN (secondary_roles);


-- ==========================================================================
-- supabase/migrations/20260822000000_dismissed_duplicate_pairs.sql
-- ==========================================================================

-- Duplicate pairs the team has already ruled on.
--
-- The rolodex flags contacts that look like the same person (same email,
-- same phone, same name through a nickname or a typo — see
-- src/lib/duplicate-contacts.ts). Some of those really are two people, and
-- once someone says so the pair must stay quiet for everyone, not just in
-- the browser that dismissed it.
--
-- Each entry is the two contact ids sorted and joined with '::', so the key
-- is the same whichever record was looked at first. localStorage still holds
-- the instant copy; this column is what makes the decision stick across
-- devices and teammates (see src/lib/team-prefs.ts).

ALTER TABLE public.organizations
  ADD COLUMN IF NOT EXISTS dismissed_duplicate_pairs JSONB DEFAULT '[]'::jsonb;


-- ==========================================================================
-- supabase/migrations/20260822000000_editor_card_scope.sql
-- ==========================================================================

-- Scope a freelance editor's account to the cards they are actually assigned.
--
-- 20260813000000 added the `editor` role and left the database alone, on the
-- reasoning that what an account can *reach* is decided in the app
-- (src/lib/roles.ts). That holds for the navigation, but not for the data: the
-- anon key ships in the page bundle, so an editor account has always been able
-- to open a console and read — or write — every row the "Authenticated full
-- access" policies cover. For an outside freelancer that means every
-- production, every contact's phone number, the budget, and the vault.
--
-- This migration makes the editor scope a database rule instead of a UI one:
--
--   * jobs         → SELECT/UPDATE only cards assigned to them, and only the
--                    board columns (a trigger enforces the column list)
--   * job_todos    → the delivery checklist on those same cards
--   * contacts     → their own Rolodex row and nothing else
--   * profiles     → their own row (scratch notes, display name)
--   * organizations→ read-only (the board's column definitions live there)
--   * user_roles   → their own row rather than the whole team roster
--   * everything else covered by 20260706000002 → no access at all
--
-- Nothing changes for admin, staff, or client accounts.

-- ---------------------------------------------------------------------------
-- 1. Link an account to a Rolodex contact.
-- ---------------------------------------------------------------------------
-- Assignment on the board is jobs.editor_id → contacts.id, but an account is
-- an auth user. Matching the two by email works until someone signs up with a
-- different address than the one in the Rolodex, and silently hands them an
-- empty board with no way to tell why. The link is now explicit, set when the
-- account is created (Settings → Team), with the email match kept as a
-- fallback so accounts made before this migration keep working.
ALTER TABLE public.user_roles
  ADD COLUMN IF NOT EXISTS contact_id UUID REFERENCES public.contacts(id) ON DELETE SET NULL;

CREATE INDEX IF NOT EXISTS user_roles_contact_id_idx ON public.user_roles (contact_id);

-- ---------------------------------------------------------------------------
-- 2. Helpers.
-- ---------------------------------------------------------------------------
-- SECURITY DEFINER because these are called from policies on the very tables
-- they read: a plain query would be filtered by the policy being evaluated
-- (contacts) or recurse into it (user_roles). They take no arguments that
-- could widen what they answer for — the identity always comes from auth.uid()
-- — so definer rights cannot be turned into a lookup of someone else's row.

CREATE OR REPLACE FUNCTION public.current_app_role()
RETURNS TEXT
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT role FROM public.user_roles WHERE id = auth.uid();
$$;

-- Which Rolodex contact is this account? The explicit link first, then the
-- email match for accounts that predate it. Parameterised so the API route can
-- ask the same question about the caller it just authenticated: the route and
-- the policies have to agree on who someone is, and the only way to guarantee
-- that is for both to read the same definition.
CREATE OR REPLACE FUNCTION public.contact_id_for_user(target_user UUID)
RETURNS UUID
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT COALESCE(
    (SELECT ur.contact_id FROM public.user_roles ur WHERE ur.id = target_user),
    -- Ordered so the answer is stable when a duplicate contact carries the
    -- same address.
    (SELECT c.id
       FROM public.user_roles ur
       JOIN public.contacts c ON LOWER(c.email) = LOWER(ur.email)
      WHERE ur.id = target_user AND ur.email IS NOT NULL AND ur.email <> ''
      ORDER BY c.created_at NULLS LAST, c.id
      LIMIT 1)
  );
$$;

CREATE OR REPLACE FUNCTION public.current_contact_id()
RETURNS UUID
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT public.contact_id_for_user(auth.uid());
$$;

-- True when the caller is one of the scoped outside accounts. Every "team"
-- policy below is re-issued as "…and not this", so a role added to this
-- function is locked out of everything by default and opened up deliberately.
CREATE OR REPLACE FUNCTION public.is_scoped_editor()
RETURNS BOOLEAN
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  -- COALESCE, not a bare comparison: an account with no user_roles row yet (a
  -- first sign-in, mid self-provision) would otherwise answer NULL, and every
  -- "NOT is_scoped_editor()" policy below would deny rather than allow. A
  -- missing role has always meant "not scoped", and still does.
  SELECT COALESCE(public.current_app_role() = 'editor', FALSE);
$$;

-- Is this card assigned to the caller? Definer rights matter here: called from
-- job_todos' policy, an invoker-rights lookup would be filtered by the jobs
-- policy and the answer would depend on evaluation order.
CREATE OR REPLACE FUNCTION public.editor_owns_job(target_job UUID)
RETURNS BOOLEAN
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT EXISTS (
    SELECT 1
      FROM public.jobs j
     WHERE j.id = target_job
       AND j.editor_id IS NOT NULL
       AND j.editor_id = public.current_contact_id()
  );
$$;

REVOKE ALL ON FUNCTION public.contact_id_for_user(UUID) FROM PUBLIC;
-- Only the server may ask about an account other than the caller's own; a
-- signed-in browser gets current_contact_id(), which can only answer for itself.
GRANT EXECUTE ON FUNCTION public.contact_id_for_user(UUID) TO service_role;
REVOKE ALL ON FUNCTION public.current_app_role() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.current_contact_id() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.is_scoped_editor() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.editor_owns_job(UUID) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.current_app_role() TO authenticated;
GRANT EXECUTE ON FUNCTION public.current_contact_id() TO authenticated;
GRANT EXECUTE ON FUNCTION public.is_scoped_editor() TO authenticated;
GRANT EXECUTE ON FUNCTION public.editor_owns_job(UUID) TO authenticated;

-- ---------------------------------------------------------------------------
-- 3. Re-issue the team-wide policies with the editor excluded.
-- ---------------------------------------------------------------------------
-- Permissive policies are OR'd together, so narrowing has to happen inside the
-- existing policy rather than alongside it. Every table listed in
-- 20260706000002 (plus jobs, whose policy was re-created by 20260806000001)
-- keeps exactly the access it has today for everyone who is not an editor.
DO $$
DECLARE
  t TEXT;
  team_tables TEXT[] := ARRAY[
    'jobs', 'contacts', 'clients', 'projects', 'job_roles', 'job_schedules',
    'job_scenes', 'job_shotlist', 'job_todos', 'job_templates',
    'gear_templates', 'organizations', 'profiles', 'notification_channels',
    'notification_events', 'vault_meta', 'vault_items', 'budget_items',
    'calendar_events', 'social_campaigns', 'social_campaign_tasks',
    'social_deliverables', 'social_links', 'social_posts'
  ];
BEGIN
  FOREACH t IN ARRAY team_tables
  LOOP
    IF EXISTS (SELECT 1 FROM pg_tables WHERE schemaname = 'public' AND tablename = t) THEN
      EXECUTE format('DROP POLICY IF EXISTS "Authenticated full access" ON public.%I', t);
      EXECUTE format(
        'CREATE POLICY "Authenticated full access" ON public.%I FOR ALL TO authenticated '
        'USING (NOT public.is_scoped_editor()) WITH CHECK (NOT public.is_scoped_editor())', t);
    END IF;
  END LOOP;
END $$;

-- ---------------------------------------------------------------------------
-- 4. Hand the editor back exactly the board.
-- ---------------------------------------------------------------------------

-- Cards assigned to them. No INSERT and no DELETE policy: an editor cannot
-- create or destroy a production. The WITH CHECK repeats the ownership test so
-- an update cannot hand the card to someone else — or to nobody — which would
-- otherwise let it disappear off their board irreversibly.
DROP POLICY IF EXISTS "Editors read their assigned cards" ON public.jobs;
CREATE POLICY "Editors read their assigned cards"
  ON public.jobs FOR SELECT
  TO authenticated
  USING (public.is_scoped_editor() AND editor_id = public.current_contact_id());

DROP POLICY IF EXISTS "Editors update their assigned cards" ON public.jobs;
CREATE POLICY "Editors update their assigned cards"
  ON public.jobs FOR UPDATE
  TO authenticated
  USING (public.is_scoped_editor() AND editor_id = public.current_contact_id())
  WITH CHECK (public.is_scoped_editor() AND editor_id = public.current_contact_id());

-- The delivery checklist on those cards.
DROP POLICY IF EXISTS "Editors work their assigned checklists" ON public.job_todos;
CREATE POLICY "Editors work their assigned checklists"
  ON public.job_todos FOR ALL
  TO authenticated
  USING (public.is_scoped_editor() AND public.editor_owns_job(job_id))
  WITH CHECK (public.is_scoped_editor() AND public.editor_owns_job(job_id));

-- Their own Rolodex row — the board hydrates the assignee on each card, and
-- with this it hydrates to them and stops there. The rest of the Rolodex
-- (every crew member's phone number and address) stays closed.
DROP POLICY IF EXISTS "Editors read their own contact" ON public.contacts;
CREATE POLICY "Editors read their own contact"
  ON public.contacts FOR SELECT
  TO authenticated
  USING (public.is_scoped_editor() AND id = public.current_contact_id());

-- Their own profile row: display name and the per-user scratch pad, which is
-- the one non-tracker widget the role is allowed to mount.
DROP POLICY IF EXISTS "Editors manage their own profile" ON public.profiles;
CREATE POLICY "Editors manage their own profile"
  ON public.profiles FOR ALL
  TO authenticated
  USING (public.is_scoped_editor() AND id = auth.uid())
  WITH CHECK (public.is_scoped_editor() AND id = auth.uid());

-- The board's column definitions and branding live on the org row. Read-only:
-- an editor renaming or deleting a column would do it for the whole studio.
DROP POLICY IF EXISTS "Editors read org settings" ON public.organizations;
CREATE POLICY "Editors read org settings"
  ON public.organizations FOR SELECT
  TO authenticated
  USING (public.is_scoped_editor());

-- ---------------------------------------------------------------------------
-- 5. Stop the roster being readable by an outside account.
-- ---------------------------------------------------------------------------
-- 20260806000000 restricted user_roles to authenticated users, which was the
-- right call for the team but still lets a freelancer enumerate every
-- teammate's email and role. Reads stay open within the team; an editor sees
-- their own row. The email arm keeps the login path's self-healing lookup
-- working, which runs before the account's id is known to the table.
DROP POLICY IF EXISTS "Authenticated read" ON public.user_roles;
CREATE POLICY "Authenticated read"
  ON public.user_roles FOR SELECT
  TO authenticated
  USING (
    NOT public.is_scoped_editor()
    OR id = auth.uid()
    OR LOWER(email) = LOWER(COALESCE(auth.jwt() ->> 'email', ''))
  );

-- ---------------------------------------------------------------------------
-- 6. Which columns an editor may write.
-- ---------------------------------------------------------------------------
-- RLS decides rows, not columns, so without this an editor could rewrite the
-- client name, the rate, or the share token on a card they happen to be on.
-- The whitelist is the board: stage, notes, labels, deadline, review and
-- delivery links, and the creative fields. Anything else is rejected outright
-- rather than silently dropped, so a UI that starts sending a field it
-- shouldn't fails loudly in testing instead of quietly in production.
CREATE OR REPLACE FUNCTION public.enforce_editor_job_columns()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public, pg_temp
AS $$
DECLARE
  editable TEXT[] := ARRAY[
    'edit_status', 'edit_notes', 'edit_labels', 'due_date',
    'review_link', 'drive_folder_url', 'links',
    'creative_brief', 'color_palette', 'updated_at'
  ];
  old_row JSONB;
  new_row JSONB;
  col TEXT;
BEGIN
  -- Checked first so an ordinary team update costs one function call and no
  -- row serialisation.
  IF NOT public.is_scoped_editor() THEN
    RETURN NEW;
  END IF;

  old_row := to_jsonb(OLD);
  new_row := to_jsonb(NEW);

  FOR col IN SELECT jsonb_object_keys(new_row)
  LOOP
    IF NOT (col = ANY (editable)) AND (new_row -> col) IS DISTINCT FROM (old_row -> col) THEN
      RAISE EXCEPTION 'An editor account may not change jobs.% on an edit card', col
        USING ERRCODE = '42501';
    END IF;
  END LOOP;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS enforce_editor_job_columns ON public.jobs;
CREATE TRIGGER enforce_editor_job_columns
  BEFORE UPDATE ON public.jobs
  FOR EACH ROW
  EXECUTE FUNCTION public.enforce_editor_job_columns();


-- ==========================================================================
-- supabase/migrations/20260822000000_studio_calendar.sql
-- ==========================================================================

-- One studio calendar, not one per person.
--
-- Slate pushes a production to Google using whichever account happened to hit
-- Save, so a shoot booked by a producer landed on the *producer's* calendar and
-- never reached anyone else's. jobs.google_event_id is a single column — one
-- job maps to exactly one Google event — so the data model only ever supported
-- one calendar for the whole studio. This flag says which one it is.
--
-- The partial unique index enforces the "one" half: at most one row may carry
-- true, so designating a new studio calendar has to clear the old one first.

ALTER TABLE public.google_tokens
  ADD COLUMN IF NOT EXISTS is_studio_calendar BOOLEAN NOT NULL DEFAULT FALSE;

CREATE UNIQUE INDEX IF NOT EXISTS idx_google_tokens_studio_calendar
  ON public.google_tokens (is_studio_calendar)
  WHERE is_studio_calendar;


-- ==========================================================================
-- supabase/migrations/20260822000001_edit_time_tracking.sql
-- ==========================================================================

-- Time tracking on an edit card.
--
-- An editor starts a timer on the card they are working, stops it when they
-- stop, and the studio gets an hours figure per production it can invoice or
-- budget against. That makes the table a billing record, so it is built to be
-- one rather than to be a convenience:
--
--   Every timestamp is written by the database. Nothing is taken from the
--   browser's clock, which the person being billed for controls. The API route
--   inserts without timestamps and lets the defaults and the trigger below
--   supply them.
--
--   The table has no INSERT, UPDATE, or DELETE policy. Writes are impossible
--   with the anon key that ships in the page bundle, whoever is signed in; they
--   only happen through /api/edits/time, which proves the caller's identity
--   from their bearer token and checks the card is theirs. Reads are the
--   caller's own entries, plus everything for admin and staff.
--
--   A started entry is append-only. The trigger refuses to move started_at, to
--   re-open a stopped entry, to reassign an entry to another job or another
--   person, or to record a span that ends in the future — and it refuses those
--   for the service role too, so a bug in the route cannot rewrite history.
--
--   One timer per person at a time, enforced by a unique index rather than by
--   the UI, so a second tab or a stale phone cannot double-bill an hour.

CREATE TABLE IF NOT EXISTS public.edit_time_entries (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  -- The card. CASCADE: a deleted production takes its time log with it.
  job_id UUID NOT NULL REFERENCES public.jobs(id) ON DELETE CASCADE,
  -- Who logged it, as an auth account rather than a Rolodex contact, so the
  -- row is attributable to a login and survives contact edits.
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  -- Denormalised for display, so the board can label an entry without reading
  -- the roster (which an editor account cannot).
  user_email TEXT,
  -- The Rolodex contact the account was linked to when the entry was made.
  contact_id UUID REFERENCES public.contacts(id) ON DELETE SET NULL,
  started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  -- NULL means running.
  ended_at TIMESTAMPTZ,
  -- Maintained by the trigger from the two timestamps, never by the caller, so
  -- it can never disagree with them.
  duration_seconds INTEGER,
  -- 'timer' was measured; 'manual' was typed in afterwards. Kept apart so
  -- someone reviewing an invoice can see which is which.
  source TEXT NOT NULL DEFAULT 'timer' CHECK (source IN ('timer', 'manual')),
  note TEXT,
  -- Set when a forgotten timer was closed at the cap rather than by its owner.
  auto_closed BOOLEAN NOT NULL DEFAULT FALSE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

  CONSTRAINT edit_time_entries_span CHECK (ended_at IS NULL OR ended_at >= started_at),
  -- Backstop under the 12-hour auto-close: no single entry can ever claim a
  -- day and a half.
  CONSTRAINT edit_time_entries_max_span
    CHECK (ended_at IS NULL OR ended_at <= started_at + INTERVAL '24 hours'),
  CONSTRAINT edit_time_entries_note_len CHECK (note IS NULL OR char_length(note) <= 500)
);

-- One running timer per person, database-side. A second start attempt fails on
-- this index rather than quietly creating an overlapping span.
CREATE UNIQUE INDEX IF NOT EXISTS edit_time_entries_one_running_per_user
  ON public.edit_time_entries (user_id) WHERE ended_at IS NULL;

CREATE INDEX IF NOT EXISTS edit_time_entries_job_idx
  ON public.edit_time_entries (job_id, started_at DESC);
CREATE INDEX IF NOT EXISTS edit_time_entries_user_idx
  ON public.edit_time_entries (user_id, started_at DESC);

-- ---------------------------------------------------------------------------
-- Append-only enforcement.
-- ---------------------------------------------------------------------------
-- SECURITY INVOKER and no role test: this applies to the service role as well,
-- which is the point. The route holds the service key, so the only thing that
-- can stop the route rewriting a stopped entry is a rule below it.
CREATE OR REPLACE FUNCTION public.guard_edit_time_entry()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public, pg_temp
AS $$
DECLARE
  -- Small allowance for clock skew between the app server and the database.
  future_slack INTERVAL := INTERVAL '1 minute';
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.id <> OLD.id
       OR NEW.job_id <> OLD.job_id
       OR NEW.user_id <> OLD.user_id
       OR NEW.started_at <> OLD.started_at
       OR NEW.source <> OLD.source
       OR NEW.created_at <> OLD.created_at THEN
      RAISE EXCEPTION 'A time entry''s card, owner, start, and source are fixed once written'
        USING ERRCODE = '42501';
    END IF;

    IF OLD.ended_at IS NOT NULL AND NEW.ended_at IS DISTINCT FROM OLD.ended_at THEN
      RAISE EXCEPTION 'A stopped time entry cannot be re-opened or re-timed'
        USING ERRCODE = '42501';
    END IF;

    NEW.updated_at := NOW();
  END IF;

  IF NEW.started_at > NOW() + future_slack THEN
    RAISE EXCEPTION 'A time entry cannot start in the future' USING ERRCODE = '22007';
  END IF;
  IF NEW.ended_at IS NOT NULL AND NEW.ended_at > NOW() + future_slack THEN
    RAISE EXCEPTION 'A time entry cannot end in the future' USING ERRCODE = '22007';
  END IF;

  NEW.duration_seconds := CASE
    WHEN NEW.ended_at IS NULL THEN NULL
    ELSE GREATEST(0, FLOOR(EXTRACT(EPOCH FROM (NEW.ended_at - NEW.started_at)))::INTEGER)
  END;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS guard_edit_time_entry ON public.edit_time_entries;
CREATE TRIGGER guard_edit_time_entry
  BEFORE INSERT OR UPDATE ON public.edit_time_entries
  FOR EACH ROW
  EXECUTE FUNCTION public.guard_edit_time_entry();

-- ---------------------------------------------------------------------------
-- Forgotten timers.
-- ---------------------------------------------------------------------------
-- A timer left running overnight is the common failure, and left alone it both
-- bills a night's sleep and blocks the next day's start through the unique
-- index. Anything still running after the cap is closed at the cap and marked,
-- so the number is visibly a truncation rather than a measurement. The route
-- calls this before it starts or lists a timer, so no scheduler is required.
CREATE OR REPLACE FUNCTION public.close_stale_edit_timers(max_hours INTEGER DEFAULT 12)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  closed INTEGER;
  cap INTERVAL := make_interval(hours => GREATEST(1, LEAST(24, COALESCE(max_hours, 12))));
BEGIN
  UPDATE public.edit_time_entries
     SET ended_at = started_at + cap,
         auto_closed = TRUE
   WHERE ended_at IS NULL
     AND started_at < NOW() - cap;
  GET DIAGNOSTICS closed = ROW_COUNT;
  RETURN closed;
END;
$$;

-- Only the route may run it: no signed-in account can reach in and close, or
-- extend, a running timer.
REVOKE ALL ON FUNCTION public.close_stale_edit_timers(INTEGER) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.close_stale_edit_timers(INTEGER) TO service_role;

-- ---------------------------------------------------------------------------
-- The three ways an entry is written.
-- ---------------------------------------------------------------------------
-- Timestamps come from NOW() inside these functions, so the recorded time is
-- the database's clock and nothing else — not the browser's, and not the app
-- server's. /api/edits/time decides *whether* a caller may log time (identity
-- from their bearer token, assignment from the card); these decide *what* gets
-- written. Both halves have to agree for a row to exist.
--
-- SECURITY DEFINER, executable by the service role only: a signed-in account
-- cannot call them directly with the anon key.

CREATE OR REPLACE FUNCTION public.start_edit_timer(
  target_job UUID,
  target_user UUID,
  target_email TEXT DEFAULT NULL,
  target_contact UUID DEFAULT NULL
)
RETURNS public.edit_time_entries
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  created public.edit_time_entries;
BEGIN
  INSERT INTO public.edit_time_entries (job_id, user_id, user_email, contact_id, started_at, source)
  VALUES (target_job, target_user, target_email, target_contact, NOW(), 'timer')
  RETURNING * INTO created;
  RETURN created;
END;
$$;

-- Stops the caller's running timer. Scoped by user_id rather than by entry id
-- alone, so passing someone else's entry stops nothing instead of stopping
-- theirs. Returns NULL when there was nothing running.
CREATE OR REPLACE FUNCTION public.stop_edit_timer(
  target_user UUID,
  target_entry UUID DEFAULT NULL
)
RETURNS public.edit_time_entries
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  stopped public.edit_time_entries;
BEGIN
  UPDATE public.edit_time_entries
     SET ended_at = NOW()
   WHERE user_id = target_user
     AND ended_at IS NULL
     AND (target_entry IS NULL OR id = target_entry)
  RETURNING * INTO stopped;
  RETURN stopped;
END;
$$;

-- A span typed in after the fact, for the session someone forgot to time. It
-- still ends at NOW() and is still measured in the database; only its length is
-- the caller's word, which is why it is bounded here as well as in the route
-- and marked 'manual' so an invoice can tell the two apart.
CREATE OR REPLACE FUNCTION public.log_manual_edit_time(
  target_job UUID,
  target_user UUID,
  minutes INTEGER,
  target_email TEXT DEFAULT NULL,
  target_contact UUID DEFAULT NULL,
  entry_note TEXT DEFAULT NULL
)
RETURNS public.edit_time_entries
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  created public.edit_time_entries;
BEGIN
  IF minutes IS NULL OR minutes <= 0 OR minutes > 720 THEN
    RAISE EXCEPTION 'A manual entry must be between 1 minute and 12 hours'
      USING ERRCODE = '22003';
  END IF;

  INSERT INTO public.edit_time_entries (
    job_id, user_id, user_email, contact_id, started_at, ended_at, source, note
  )
  VALUES (
    target_job, target_user, target_email, target_contact,
    NOW() - make_interval(mins => minutes), NOW(), 'manual', NULLIF(entry_note, '')
  )
  RETURNING * INTO created;
  RETURN created;
END;
$$;

REVOKE ALL ON FUNCTION public.start_edit_timer(UUID, UUID, TEXT, UUID) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.stop_edit_timer(UUID, UUID) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.log_manual_edit_time(UUID, UUID, INTEGER, TEXT, UUID, TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.start_edit_timer(UUID, UUID, TEXT, UUID) TO service_role;
GRANT EXECUTE ON FUNCTION public.stop_edit_timer(UUID, UUID) TO service_role;
GRANT EXECUTE ON FUNCTION public.log_manual_edit_time(UUID, UUID, INTEGER, TEXT, UUID, TEXT) TO service_role;

-- ---------------------------------------------------------------------------
-- Access.
-- ---------------------------------------------------------------------------
ALTER TABLE public.edit_time_entries ENABLE ROW LEVEL SECURITY;

-- Your own log, always. Admin and staff see the whole studio's, because that
-- is the number they invoice and budget from. An editor sees only their own —
-- what a colleague bills is not theirs to read.
DROP POLICY IF EXISTS "Read your own time" ON public.edit_time_entries;
CREATE POLICY "Read your own time"
  ON public.edit_time_entries FOR SELECT
  TO authenticated
  USING (
    user_id = auth.uid()
    OR public.current_app_role() IN ('admin', 'staff')
  );

-- Deliberately no INSERT / UPDATE / DELETE policy. Writes go through
-- /api/edits/time with the service key, which is the only place the assignment
-- check and the bounds live.


-- ==========================================================================
-- supabase/migrations/20260822000001_marker_fanout_and_orphans.sql
-- ==========================================================================

-- Two follow-ups to the studio-calendar change.
--
-- 1. Markers fan out per person. Productions belong on the one studio calendar,
--    but a Hold, a Travel Day or an Out of Office is something each person
--    wants on their own calendar. calendar_events.google_event_id holds a
--    single id, so mirroring a marker to several calendars needs a row per
--    (marker, account) instead. The legacy column stays exactly as it is: it
--    identifies markers imported *from* Google, which is a different job.
--
-- 2. Jobs record which calendar their event is actually on. Without it, a
--    production pushed to someone's personal calendar before the studio one
--    was designated leaves an untouchable copy behind — nothing knows whose
--    calendar to look in to clean it up.

CREATE TABLE IF NOT EXISTS public.calendar_event_google_links (
  event_id UUID NOT NULL REFERENCES public.calendar_events(id) ON DELETE CASCADE,
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  google_event_id TEXT NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY (event_id, user_id)
);

-- One Google event is one marker copy: catches a link row pointing at an event
-- another row already claims on the same calendar.
CREATE UNIQUE INDEX IF NOT EXISTS idx_cegl_user_google_event
  ON public.calendar_event_google_links (user_id, google_event_id);

-- Reverse lookup, for cleaning up after an event cancelled on Google's side.
CREATE INDEX IF NOT EXISTS idx_cegl_google_event
  ON public.calendar_event_google_links (google_event_id);

-- Tokens-adjacent: only the service role touches this, same as google_tokens.
-- RLS on with no policies denies every anon/authenticated read and write.
ALTER TABLE public.calendar_event_google_links ENABLE ROW LEVEL SECURITY;

ALTER TABLE public.jobs
  ADD COLUMN IF NOT EXISTS google_calendar_user_id UUID;


-- ==========================================================================
-- supabase/migrations/20260823000000_schema_migrations.sql
-- ==========================================================================

-- A record of which migrations have actually been run.
--
-- Migrations here are applied by hand, pasted into Supabase's SQL editor, and
-- until now nothing wrote down that it happened, so answering "is the database
-- up to date?" meant reading git history and inferring. That is worse than it
-- sounds, because several code paths deliberately fall back when a migration
-- has not run (see the marker push in src/lib/marker-sync.ts): a missing
-- migration does not raise an error, it quietly keeps the old behaviour.
--
-- `version` is the filename without `.sql`, not the timestamp prefix. Three
-- files share the prefix 20260822000000 and two share 20260822000001, because
-- parallel branches each picked the same timestamp; the descriptive half is
-- what actually distinguishes them. See docs/MIGRATIONS.md.
--
-- No policies are granted. Only the service role reads this, the same posture
-- as google_tokens and calendar_event_google_links.

CREATE TABLE IF NOT EXISTS public.schema_migrations (
  version TEXT PRIMARY KEY,
  applied_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  -- How this row knows the migration ran:
  --   'recorded' — the migration inserted this itself, as it ran.
  --   'verified' — the backfill below found the change present in the schema.
  --   'assumed'  — the backfill could not check; see the note in that section.
  basis TEXT NOT NULL DEFAULT 'recorded'
);

-- Defensive, in case an earlier draft of this file created the table.
ALTER TABLE public.schema_migrations
  ADD COLUMN IF NOT EXISTS basis TEXT NOT NULL DEFAULT 'recorded';

ALTER TABLE public.schema_migrations ENABLE ROW LEVEL SECURITY;

-- ---------------------------------------------------------------------------
-- Probes. Each asks the live schema whether one migration's change is present,
-- rather than taking anyone's word for it. Created in pg_temp so they vanish
-- with the session and leave nothing behind.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION pg_temp.has_rel(name TEXT) RETURNS BOOLEAN
  LANGUAGE sql STABLE AS $$
    -- Tables and indexes both live in pg_class, so this covers both.
    SELECT to_regclass('public.' || quote_ident(name)) IS NOT NULL;
  $$;

CREATE OR REPLACE FUNCTION pg_temp.has_col(tbl TEXT, col TEXT) RETURNS BOOLEAN
  LANGUAGE sql STABLE AS $$
    SELECT EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = tbl AND column_name = col
    );
  $$;

CREATE OR REPLACE FUNCTION pg_temp.has_policy(tbl TEXT, pol TEXT) RETURNS BOOLEAN
  LANGUAGE sql STABLE AS $$
    SELECT EXISTS (
      SELECT 1 FROM pg_policies
      WHERE schemaname = 'public' AND tablename = tbl AND policyname = pol
    );
  $$;

CREATE OR REPLACE FUNCTION pg_temp.in_realtime(tbl TEXT) RETURNS BOOLEAN
  LANGUAGE sql STABLE AS $$
    SELECT EXISTS (
      SELECT 1 FROM pg_publication_tables
      WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = tbl
    );
  $$;

CREATE OR REPLACE FUNCTION pg_temp.google_tokens_locked_down() RETURNS BOOLEAN
  LANGUAGE sql STABLE AS $$
    -- 20260706000002 stripped every policy off google_tokens and turned RLS on,
    -- leaving it service-role only. Nothing since re-adds a policy there, so
    -- "RLS on and no policies" is that migration's durable signature.
    SELECT COALESCE(
      (SELECT c.relrowsecurity FROM pg_class c WHERE c.oid = to_regclass('public.google_tokens')),
      FALSE
    ) AND NOT EXISTS (
      SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'google_tokens'
    );
  $$;

CREATE OR REPLACE FUNCTION pg_temp.user_roles_allows_editor() RETURNS BOOLEAN
  LANGUAGE sql STABLE AS $$
    -- 20260813000000 rewrote the role CHECK constraint to admit 'editor'.
    SELECT EXISTS (
      SELECT 1
      FROM pg_constraint c
      JOIN pg_class t ON t.oid = c.conrelid
      JOIN pg_namespace n ON n.oid = t.relnamespace
      WHERE n.nspname = 'public' AND t.relname = 'user_roles'
        AND c.contype = 'c' AND pg_get_constraintdef(c.oid) ILIKE '%editor%'
    );
  $$;

-- ---------------------------------------------------------------------------
-- Backfill: the 52 migrations that existed on 2026-08-23.
--
-- Each row is recorded ONLY if its probe finds the change in this database, so
-- this asserts nothing it has not checked. A migration you never ran simply
-- does not get a row, and check-applied.mjs will list it as pending.
--
-- Two rows are 'assumed' rather than verified. Both did nothing but create an
-- RLS policy that a LATER migration dropped and replaced, so there is no trace
-- of their own effect left to look for:
--   20260619000007_public_read_user_roles        (superseded by 20260806000000)
--   20260806000000_user_roles_authenticated_read (superseded by editor_card_scope)
-- They are gated on user_roles.contact_id — the mark of 20260822000000_editor_
-- card_scope, which is what dropped the last of their policies. A database that
-- has reached that point has passed through theirs. That is an inference from a
-- later migration's evidence, not a check of their own, which is why the basis
-- is 'assumed': on a database that never got that far, neither is recorded.
--
-- Safe to run twice: ON CONFLICT DO NOTHING. Re-running after applying a
-- missing migration will pick it up.
-- ---------------------------------------------------------------------------

INSERT INTO public.schema_migrations (version, basis)
SELECT version, basis
FROM (VALUES
  ('20260610000000_add_job_financials',                     'verified',  pg_temp.has_rel('job_templates')),
  ('20260610000001_add_job_links',                          'verified',  pg_temp.has_col('jobs','links')),
