-- ==========================================================================
-- supabase/migrations/20260921000000_editor_deliverables.sql
-- ==========================================================================

-- Let an editor see the deliverables on the cards they are assigned.
--
-- The Edit Tracker card now lists the deliverables a job was given on Slate,
-- so the producer builds the job once and the editor cuts from the same list.
-- 20260822000000 shut editors out of social_deliverables entirely, which would
-- hand them an empty section on every card.
--
-- Read, plus update so they can move a cut to "delivered". No INSERT and no
-- DELETE: what the client is owed is the producer's call. The WITH CHECK
-- repeats the ownership test so an update cannot re-point a row at another job.

DROP POLICY IF EXISTS "Editors read their assigned deliverables" ON public.social_deliverables;
CREATE POLICY "Editors read their assigned deliverables"
  ON public.social_deliverables FOR SELECT
  TO authenticated
  USING (public.is_scoped_editor() AND public.editor_owns_job(job_id));

DROP POLICY IF EXISTS "Editors update their assigned deliverables" ON public.social_deliverables;
CREATE POLICY "Editors update their assigned deliverables"
  ON public.social_deliverables FOR UPDATE
  TO authenticated
  USING (public.is_scoped_editor() AND public.editor_owns_job(job_id))
  WITH CHECK (public.is_scoped_editor() AND public.editor_owns_job(job_id));

-- RLS decides rows, not columns. Without this an editor could rename a cut,
-- change its format, or move it to another client's list on the Social tab.
-- Status is the one field that is theirs; anything else is rejected outright,
-- the same posture as enforce_editor_job_columns on jobs.
CREATE OR REPLACE FUNCTION public.enforce_editor_deliverable_columns()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public, pg_temp
AS $$
DECLARE
  editable TEXT[] := ARRAY['status'];
  old_row JSONB;
  new_row JSONB;
  col TEXT;
BEGIN
  IF NOT public.is_scoped_editor() THEN
    RETURN NEW;
  END IF;

  old_row := to_jsonb(OLD);
  new_row := to_jsonb(NEW);

  FOR col IN SELECT jsonb_object_keys(new_row)
  LOOP
    IF NOT (col = ANY (editable)) AND (new_row -> col) IS DISTINCT FROM (old_row -> col) THEN
      RAISE EXCEPTION 'An editor account may not change social_deliverables.%', col
        USING ERRCODE = '42501';
    END IF;
  END LOOP;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS enforce_editor_deliverable_columns ON public.social_deliverables;
CREATE TRIGGER enforce_editor_deliverable_columns
  BEFORE UPDATE ON public.social_deliverables
  FOR EACH ROW
  EXECUTE FUNCTION public.enforce_editor_deliverable_columns();

INSERT INTO public.schema_migrations (version) VALUES ('20260921000000_editor_deliverables')
  ON CONFLICT (version) DO NOTHING;


-- ==========================================================================
-- supabase/migrations/20260930235620_lock_down_agency_tables.sql
-- ==========================================================================

-- Close the anonymous access the 2026-08-27 migrations opened.
--
-- 20260827000000_meeting_notes and 20260827000001_agency_expansion created
-- four tables with an "Allow all for now" policy: FOR ALL USING (true), with no
-- role. That covers `anon`, and the anon key ships in the page bundle, so
-- anyone could read — or write — meeting notes, client onboarding briefs,
-- review comments and scouted locations from a browser console. It "matched
-- other project tables" only as they were before 20260706000002 hardened them.
--
-- The tables are in production (and empty as of 2026-09-30), so the policy is
-- live even though neither file was recorded in schema_migrations. This
-- replaces it with the posture every other internal table has: signed-in team
-- accounts, not freelance editors (20260822000000). Client accounts keep
-- access, which the Client Review and Client Onboarding tabs rely on.
--
-- Safe to run whether or not the two August files were ever pasted in: every
-- table is guarded by an existence check. Running it also records those two
-- files, since their tables and jobs columns already exist; paste them only
-- if the tables below turn out to be missing.

DO $$
DECLARE
  t TEXT;
  pol RECORD;
  agency_tables TEXT[] := ARRAY['meeting_notes', 'locations', 'client_intakes', 'video_reviews'];
BEGIN
  FOREACH t IN ARRAY agency_tables
  LOOP
    IF EXISTS (SELECT 1 FROM pg_tables WHERE schemaname = 'public' AND tablename = t) THEN
      -- Permissive policies are OR'd, so every existing one has to go, not
      -- just the one this migration knows the name of.
      FOR pol IN SELECT policyname FROM pg_policies WHERE schemaname = 'public' AND tablename = t
      LOOP
        EXECUTE format('DROP POLICY %I ON public.%I', pol.policyname, t);
      END LOOP;
      EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);
      EXECUTE format(
        'CREATE POLICY "Authenticated full access" ON public.%I FOR ALL TO authenticated '
        'USING (NOT public.is_scoped_editor()) WITH CHECK (NOT public.is_scoped_editor())', t);
    END IF;
  END LOOP;
END $$;

INSERT INTO public.schema_migrations (version) VALUES
  ('20260827000000_meeting_notes'),
  ('20260827000001_agency_expansion'),
  ('20260930235620_lock_down_agency_tables')
  ON CONFLICT (version) DO NOTHING;


-- ==========================================================================
-- supabase/migrations/20261001003149_inventory_public_read_studio_only.sql
-- ==========================================================================

-- Keep borrowed gear out of the anonymous catalog read.
--
-- The Gear Builder now saves gear borrowed from friends and rental houses into
-- `inventory` with `owner` set ("Sony A1 [Rob Douthat]"). 20260806000002 gave
-- that table an anonymous SELECT for the public /gear pages, so without this
-- every friend's name and what they lend the studio would be readable by
-- anyone with the anon key in the page bundle. The pages filter borrowed gear
-- out themselves; this makes the database agree.
--
--   anon          → studio-owned gear only (owner empty or "Zipline Media")
--   authenticated → everything, unchanged: "Authenticated full access" from
--                   20260806000001 already covers reads (Gear Builder, Slate,
--                   call sheets). "Public read" used to apply to every role;
--                   it is now scoped to anon so it can't be the wider rule.
--
-- The share page is unaffected: /api/share/gear reads with the service key.
-- The policy keeps the name "Public read" so the schema_migrations check for
-- 20260806000002 (has_policy('inventory','Public read')) stays verified.

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_tables WHERE schemaname = 'public' AND tablename = 'inventory') THEN
    DROP POLICY IF EXISTS "Public read" ON public.inventory;
    CREATE POLICY "Public read"
      ON public.inventory FOR SELECT
      TO anon
      USING (
        owner IS NULL
        OR btrim(owner) = ''
        OR lower(btrim(owner)) = 'zipline media'
      );

  END IF;
END $$;

INSERT INTO public.schema_migrations (version) VALUES ('20261001003149_inventory_public_read_studio_only')
  ON CONFLICT (version) DO NOTHING;


-- ==========================================================================
-- supabase/migrations/20261015000000_drive_tracker.sql
-- ==========================================================================

-- Drive Tracker: every SSD and transfer drive the studio owns, who has it now,
-- and the trail of everyone who has had it.
--
-- Editor drives (Samsung T5/T7/T9, 1–4 TB) live with a freelance editor for
-- the length of a job. Transfer drives are small sticks couriered to an agency
-- that should come straight back once the footage is on their server. Both get
-- forgotten, and at current storage prices a forgotten drive is real money, so
-- the row carries what it cost and when it went out.
--
-- `drives` holds the current state; `drive_events` is append-only history
-- (checked out, returned, marked lost…) written by the app on every change.
--
-- Access matches the other internal tables (20260930235620): any signed-in
-- team account reads and writes, freelance editor accounts and anon do not.

CREATE TABLE IF NOT EXISTS public.drives (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  -- What's written on the drive: "ZM-07", "Blue T9", "Transfer 3".
  label TEXT NOT NULL,
  kind TEXT NOT NULL DEFAULT 'editor' CHECK (kind IN ('editor', 'transfer')),
  model TEXT,
  capacity_tb NUMERIC(6, 2),
  serial TEXT,
  purchase_price NUMERIC(10, 2),
  status TEXT NOT NULL DEFAULT 'in_office' CHECK (status IN ('in_office', 'out', 'lost', 'retired')),
  -- Who has it while status = 'out'. Free text so an agency, a courier or a
  -- one-off editor doesn't need a Rolodex entry first.
  holder_name TEXT,
  holder_type TEXT CHECK (holder_type IN ('editor', 'agency', 'client', 'other')),
  job_id UUID REFERENCES public.jobs(id) ON DELETE SET NULL,
  checked_out_at TIMESTAMPTZ,
  expected_back DATE,
  notes TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_drives_status ON public.drives(status);

CREATE TABLE IF NOT EXISTS public.drive_events (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  drive_id UUID NOT NULL REFERENCES public.drives(id) ON DELETE CASCADE,
  action TEXT NOT NULL CHECK (action IN ('added', 'checked_out', 'returned', 'lost', 'found', 'retired', 'note')),
  holder_name TEXT,
  job_id UUID REFERENCES public.jobs(id) ON DELETE SET NULL,
  note TEXT,
  -- Who in the studio logged it.
  actor TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_drive_events_drive ON public.drive_events(drive_id, created_at DESC);

ALTER TABLE public.drives ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.drive_events ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Authenticated full access" ON public.drives;
CREATE POLICY "Authenticated full access" ON public.drives
  FOR ALL TO authenticated
  USING (NOT public.is_scoped_editor()) WITH CHECK (NOT public.is_scoped_editor());

DROP POLICY IF EXISTS "Authenticated full access" ON public.drive_events;
CREATE POLICY "Authenticated full access" ON public.drive_events
  FOR ALL TO authenticated
  USING (NOT public.is_scoped_editor()) WITH CHECK (NOT public.is_scoped_editor());

CREATE OR REPLACE FUNCTION public.touch_drives_updated_at()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = public, pg_temp
AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS touch_drives_updated_at ON public.drives;
CREATE TRIGGER touch_drives_updated_at
  BEFORE UPDATE ON public.drives
  FOR EACH ROW
  EXECUTE FUNCTION public.touch_drives_updated_at();

-- Live updates, so a drive checked in on one laptop flips on everyone's screen.
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_publication_tables WHERE pubname = 'supabase_realtime' AND tablename = 'drives') THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE public.drives;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_publication_tables WHERE pubname = 'supabase_realtime' AND tablename = 'drive_events') THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE public.drive_events;
  END IF;
END $$;

INSERT INTO public.schema_migrations (version) VALUES ('20261015000000_drive_tracker')
  ON CONFLICT (version) DO NOTHING;


-- ==========================================================================
-- supabase/migrations/20261019000000_drive_tracker_editor_access.sql
-- ==========================================================================

-- Let freelance editor accounts use the Drive Tracker.
--
-- The drives mostly live with editors, so the studio wants them to log their
-- own hand-offs: check a drive out to themselves, mark one returned, add a
-- drive they were given. 20261015000000 gave the two drive tables the usual
-- team-only posture (NOT is_scoped_editor()); this widens both to every
-- signed-in account. Anon stays shut out.
--
-- Deliberately full access, not "only the drives you hold": the studio chose
-- to give editors the same tab staff have. Their other limits are untouched.
-- They still read only their own jobs and contact, so in the tracker the
-- project picker lists just their jobs, and other people's drives show no
-- project title.

DROP POLICY IF EXISTS "Authenticated full access" ON public.drives;
CREATE POLICY "Authenticated full access" ON public.drives
  FOR ALL TO authenticated
  USING (true) WITH CHECK (true);

DROP POLICY IF EXISTS "Authenticated full access" ON public.drive_events;
CREATE POLICY "Authenticated full access" ON public.drive_events
  FOR ALL TO authenticated
  USING (true) WITH CHECK (true);

